</style></head><body><div class="toolbar"><button onclick="window.print()">چاپ / ذخیره PDF</button><button onclick="goBackToApp()">بازگشت</button></div><main class="print-sheet"><div id="fontWarning" class="font-warning">فونت انتخابی روی هاست پیدا نشد و مرورگر از فونت جایگزین استفاده می‌کند.</div><h1><?=e($title)?></h1><div class="meta"><?php if($reportPeriod!==''):?><strong class="print-report-period"><?=e($reportPeriod)?></strong><?php endif;?><span class="print-money-unit">واحد مبلغ: <?=e(SettingsService::moneyUnit($settings))?></span></div><div class="table-shell"><table class="<?= (in_array($type,['detail','customer_detail'],true)?'svo-print-detail':'') ?>"><thead><tr><?php foreach($headers as $h):?><th><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $i=>$v):$h=$headers[$i]??'';$cl=str_contains($h,'دریافتی')?'recv':(str_contains($h,'پرداختی')?'pay':(str_contains($h,'کمیسیون')?'comm':(str_contains((string)$v,'برد سایت')?'site-win':(str_contains((string)$v,'باخت سایت')?'site-loss':''))));if($h==='Member Win')$cl=(float)$v<0?'svo-mw-negative':((float)$v>0?'svo-mw-positive':'');?><td class="<?=$cl?>"><?php if(is_numeric($v)&&in_array($h,['دریافتی','پرداختی','کمیسیون'],true)):?><?=e(SettingsService::money($v,$settings))?><?php elseif($h==='Member Win'):?><?=e(SettingsService::decimal($v,$settings,2))?><?php elseif(is_numeric($v)&&str_contains($h,'دلار')):?><?=e(number_format((float)$v,2,'.',','))?><?php else:?><?=e($v)?><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php if($tot):?><table class="totals"><tr class="recv"><th>جمع دریافتی</th><td><?=e(SettingsService::money($tot['received']??0,$settings))?></td></tr><tr class="pay"><th>جمع پرداختی</th><td><?=e(SettingsService::money($tot['paid']??0,$settings))?></td></tr><tr class="comm"><th>جمع کمیسیون</th><td><?=e(SettingsService::money($tot['commission']??0,$settings))?></td></tr><?php $net=$tot['net']??(($tot['received'